import { useCompareChat } from './hooks/useCompareChat';
import { ComparisonChatInterface } from './components/ComparisonChatInterface';
import './App.css';

function App() {
  const {
    messages,
    currentMemories,
    isLoading,
    isRetrievingMemories,
    isLoadingFollowUps,
    error,
    comparison,
    sendMessage,
    clearChat,
  } = useCompareChat();

  return (
    <div className="app comparison-mode">
      <ComparisonChatInterface
        messages={messages}
        comparison={comparison}
        isLoading={isLoading}
        isRetrievingMemories={isRetrievingMemories}
        isLoadingFollowUps={isLoadingFollowUps}
        error={error}
        memories={currentMemories}
        onSendMessage={sendMessage}
        onClearChat={clearChat}
      />
    </div>
  );
}

export default App;

import { useState, useRef, useEffect } from 'react';

interface ChatInputProps {
  onSend: (message: string) => void;
  disabled: boolean;
}

export function ChatInput({ onSend, disabled }: ChatInputProps) {
  const [input, setInput] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !disabled) {
      onSend(input.trim());
      setInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      const scrollHeight = textareaRef.current.scrollHeight;
      const maxHeight = 5 * 24; // 5 lines * 24px line height
      textareaRef.current.style.height = `${Math.min(scrollHeight, maxHeight)}px`;
    }
  }, [input]);

  return (
    <form onSubmit={handleSubmit} className="chat-input-form">
      <textarea
        ref={textareaRef}
        value={input}
        onChange={(e) => setInput(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder="Ask me anything about A Song of Ice and Fire..."
        disabled={disabled}
        className="chat-input-textarea"
        rows={1}
        maxLength={1000}
      />
      <button
        type="submit"
        disabled={disabled || !input.trim()}
        className="chat-input-button"
      >
        Send
      </button>
    </form>
  );
}

